                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

    // The positional input is decompressed by the module. Without that, MAFFT reads a
    // gzipped file as an empty alignment and exits 0, so the output would be silently empty
    // rather than equal to the uncompressed run.
    test("SARS-CoV-2 scaffolds fasta - gzipped input") {
        when {
            process {
                """
                def gzipped = java.nio.file.Files.createTempDirectory('mafft_gz').resolve('scaffolds.fasta.gz')
                new java.util.zip.GZIPOutputStream(gzipped.toFile().newOutputStream()).withStream { out ->
                    out << file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fasta/scaffolds.fasta', checkIfExists: true).bytes
                }

                input[0] = [
                    [ id:'test' ],
                        file(gzipped.toString())
                    ]
                input[1] = [[:], []]
                input[2] = [[:], []]
                input[3] = [[:], []]
                input[4] = [[:], []]
                input[5] = [[:], []]
                input[6] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

